     1→/**
     2→ * HabitsEmptyStateMinimal - Main Component
     3→ *
     4→ * Ultra-minimal empty state design focused on a single question flow.
     5→ * Ask what habit the user wants, let them type or tap a suggestion,
     6→ * and create it immediately.
     7→ *
     8→ * Reference: docs/specs/empty-habit-screen/minimal-redesign.md
     9→ */
    10→
    11→import { useCallback, useRef, useState } from 'react';
    12→import { Keyboard, TextInput, View } from 'react-native';
    13→import Animated, {
    14→  useAnimatedStyle,
    15→  useReducedMotion,
    16→  withTiming,
    17→  Easing,
    18→} from 'react-native-reanimated';
    19→import { useSafeAreaInsets } from 'react-native-safe-area-context';
    20→
    21→import { useHapticFeedback } from '../../../../hooks/useHapticFeedback';
    22→import { useKeyboardVisible } from '../../../../hooks/useKeyboardVisible';
    23→import { useTimeBasedChipAnalytics } from './analytics';
    24→import { AnimatedEntrance } from './AnimatedEntrance';
    25→import { ENTRANCE_DELAYS, KEYBOARD_LAYOUT } from './animations';
    26→import { COLORS, COPY } from './constants';
    27→import { CtaButton } from './CtaButton';
    28→import { ErrorMessage } from './ErrorMessage';
    29→import { HabitInput } from './HabitInput';
    30→import { HeroIcon } from './HeroIcon';
    31→import { InlineHint } from './InlineHint';
    32→import { LoadingSkeleton } from './LoadingSkeleton';
    33→import { SuccessState } from './SuccessState';
    34→import { SuggestionChips } from './SuggestionChips';
    35→import type { HabitsEmptyStateMinimalProps, SuggestionChip } from './types';
    36→import { getTimeBasedChips } from './utils';
    37→
    38→/**
    39→ * Minimal empty state for habits screen
    40→ *
    41→ * Provides a streamlined flow for creating the first habit:
    42→ * 1. Hero icon with breathing animation
    43→ * 2. Question headline
    44→ * 3. Text input or suggestion chips
    45→ * 4. Primary CTA button
    46→ * 5. Success celebration on creation
    47→ */
    48→export function HabitsEmptyStateMinimal({
    49→  isLoading = false,
    50→  onQuickCreateHabit,
    51→  openTemplatesScreen,
    52→  openCreateHabitScreen,
    53→  onSuccessTransitionComplete,
    54→}: HabitsEmptyStateMinimalProps) {
    55→  const inputRef = useRef<TextInput>(null);
    56→  const { triggerSuccess } = useHapticFeedback();
    57→  const { isKeyboardVisible } = useKeyboardVisible();
    58→  const shouldReduceMotion = useReducedMotion();
    59→  const insets = useSafeAreaInsets();
    60→
    61→  // Extract bottom inset for use in worklet (capture at mount)
    62→  const bottomInset = insets.bottom;
    63→
    64→  // Timing config for keyboard-aware transitions
    65→  const timingConfig = {
    66→    duration: shouldReduceMotion ? 0 : KEYBOARD_LAYOUT.transitionDuration,
    67→    easing: Easing.out(Easing.ease),
    68→  };
    69→
    70→  // Animated styles for keyboard-aware compact mode
    71→  const containerAnimatedStyle = useAnimatedStyle(() => ({
    72→    justifyContent: isKeyboardVisible ? 'flex-start' : 'center',
    73→    paddingBottom: withTiming(
    74→      isKeyboardVisible ? 0 : bottomInset + 20, // +20 for breathing room above safe area
    75→      timingConfig
    76→    ),
    77→    paddingTop: withTiming(
    78→      isKeyboardVisible ? KEYBOARD_LAYOUT.topPadding : 0,
    79→      timingConfig
    80→    ),
    81→  }));
    82→
    83→  const heroAnimatedStyle = useAnimatedStyle(() => ({
    84→    transform: [
    85→      {
    86→        scale: withTiming(
    87→          isKeyboardVisible ? KEYBOARD_LAYOUT.compactHeroSize / 80 : 1,
    88→          timingConfig
    89→        ),
    90→      },
    91→    ],
    92→  }));
    93→
    94→  const headlineAnimatedStyle = useAnimatedStyle(() => ({
    95→    fontSize: withTiming(
    96→      isKeyboardVisible ? KEYBOARD_LAYOUT.compactHeadlineFontSize : 24,
    97→      timingConfig
    98→    ),
    99→    marginBottom: withTiming(isKeyboardVisible ? 16 : 32, timingConfig),
   100→    marginTop: withTiming(isKeyboardVisible ? 16 : 32, timingConfig),
   101→  }));
   102→
   103→  const chipsAnimatedStyle = useAnimatedStyle(() => ({
   104→    marginBottom: withTiming(isKeyboardVisible ? 0 : 32, timingConfig),
   105→    maxHeight: withTiming(isKeyboardVisible ? 0 : 200, timingConfig),
   106→    opacity: withTiming(isKeyboardVisible ? 0 : 1, timingConfig),
   107→    overflow: 'hidden' as const,
   108→  }));
   109→
   110→  const secondaryLinksAnimatedStyle = useAnimatedStyle(() => ({
   111→    maxHeight: withTiming(isKeyboardVisible ? 0 : 100, timingConfig),
   112→    opacity: withTiming(isKeyboardVisible ? 0 : 1, timingConfig),
   113→    overflow: 'hidden' as const,
   114→  }));
   115→
   116→  // Component state
   117→  const [inputValue, setInputValue] = useState('');
   118→  const [selectedChipIndex, setSelectedChipIndex] = useState<number | null>(
   119→    null
   120→  );
   121→  const [selectedEmoji, setSelectedEmoji] = useState<string | null>(null);
   122→  const [isCreating, setIsCreating] = useState(false);
   123→  const [successHabitName, setSuccessHabitName] = useState<string | null>(null);
   124→  const [successEmoji, setSuccessEmoji] = useState<string | null>(null);
   125→  const [errorMessage, setErrorMessage] = useState<string | null>(null);
   126→
   127→  // Analytics tracking
   128→  const analytics = useTimeBasedChipAnalytics();
   129→  const displayTimestampRef = useRef<number>(Date.now());
   130→  const selectedChipDataRef = useRef<SuggestionChip | null>(null);
   131→
   132→  // Handle chip selection - populates input with full habit name
   133→  // Tapping a selected chip deselects it and clears input
   134→  const handleChipSelect = useCallback(
   135→    (index: number, chip: SuggestionChip) => {
   136→      if (selectedChipIndex === index) {
   137→        // Deselect if tapping the same chip
   138→        setSelectedChipIndex(null);
   139→        setSelectedEmoji(null);
   140→        setInputValue('');
   141→        selectedChipDataRef.current = null;
   142→      } else {
   143→        setSelectedChipIndex(index);
   144→        setSelectedEmoji(chip.emoji);
   145→        setInputValue(chip.fullName);
   146→        selectedChipDataRef.current = chip;
   147→      }
   148→    },
   149→    [selectedChipIndex]
   150→  );
   151→
   152→  // Handle text input changes - deselects chips when typing
   153→  const handleInputChange = useCallback(
   154→    (text: string) => {
   155→      setInputValue(text);
   156→      // Deselect chips when user types manually
   157→      if (selectedChipIndex !== null) {
   158→        setSelectedChipIndex(null);
   159→        setSelectedEmoji(null);
   160→        selectedChipDataRef.current = null;
   161→
   162→        // Track manual input after viewing chips
   163→        if (text.trim().length > 0) {
   164→          const chips = getTimeBasedChips();
   165→          analytics.trackManualInputAfterChipView(text, chips);
   166→        }
   167→      }
   168→    },
   169→    [selectedChipIndex, analytics]
   170→  );
   171→
   172→  // Handle CTA button press - creates the habit
   173→  const handleCreateHabit = useCallback(async () => {
   174→    if (!inputValue.trim() || isCreating) return;
   175→
   176→    Keyboard.dismiss();
   177→    setIsCreating(true);
   178→    setErrorMessage(null);
   179→
   180→    try {
   181→      await onQuickCreateHabit(inputValue.trim());
   182→      triggerSuccess();
   183→      setSuccessHabitName(inputValue.trim());
   184→      setSuccessEmoji(selectedEmoji); // Save emoji for success state
   185→
   186→      // Track chip-to-habit conversion if a chip was selected
   187→      if (selectedChipDataRef.current && selectedChipIndex !== null) {
   188→        analytics.trackChipConvertedToHabit(
   189→          selectedChipDataRef.current,
   190→          selectedChipIndex,
   191→          displayTimestampRef.current
   192→        );
   193→      }
   194→    } catch (error) {
   195→      setIsCreating(false);
   196→      setErrorMessage(
   197→        error instanceof Error
   198→          ? error.message
   199→          : 'Failed to create habit. Please try again.'
   200→      );
   201→    }
   202→  }, [
   203→    inputValue,
   204→    isCreating,
   205→    onQuickCreateHabit,
   206→    triggerSuccess,
   207→    selectedEmoji,
   208→    selectedChipIndex,
   209→    analytics,
   210→  ]);
   211→
   212→  // Handle keyboard submit (Done button)
   213→  const handleSubmitEditing = useCallback(() => {
   214→    if (inputValue.trim() && !isCreating) {
   215→      handleCreateHabit();
   216→    }
   217→  }, [inputValue, isCreating, handleCreateHabit]);
   218→
   219→  // Handle clear input button
   220→  const handleClearInput = useCallback(() => {
   221→    setInputValue('');
   222→    setSelectedChipIndex(null);
   223→    setSelectedEmoji(null);
   224→    inputRef.current?.focus();
   225→  }, []);
   226→
   227→  // Handle "Add another habit" from success state
   228→  const handleAddAnother = useCallback(() => {
   229→    setSuccessHabitName(null);
   230→    setSuccessEmoji(null);
   231→    setInputValue('');
   232→    setSelectedChipIndex(null);
   233→    setSelectedEmoji(null);
   234→    setIsCreating(false);
   235→    // Focus input for next habit entry
   236→    setTimeout(() => inputRef.current?.focus(), 100);
   237→  }, []);
   238→
   239→  // Handle error dismiss
   240→  const handleDismissError = useCallback(() => {
   241→    setErrorMessage(null);
   242→  }, []);
   243→
   244→  // Show success state if habit was created
   245→  if (successHabitName) {
   246→    // If we have a transition callback, auto-transition after celebration
   247→    // Otherwise, show "Add another" button
   248→    const shouldAutoTransition = !!onSuccessTransitionComplete;
   249→
   250→    return (
   251→      <SuccessState
   252→        autoTransition={shouldAutoTransition}
   253→        habitEmoji={successEmoji}
   254→        habitName={successHabitName}
   255→        onAddAnother={handleAddAnother}
   256→  

